var blqs={},ordB=[]; // v107: bloquinhos (coluna BLOCO da aba ATALHOS)
g.itens.forEach(function(it){
  if(it.bloco){if(!blqs[it.bloco]){blqs[it.bloco]=[];ordB.push(it.bloco);}blqs[it.bloco].push(it);return;}
  var b=document.createElement('button');b.className='item';b.textContent=it.botao;
  if(!it.ok)b.style.opacity='.5';
  b.onclick=function(){abrirItem(it);};box.appendChild(b);
});
ordB.forEach(function(nb){
  var d=document.createElement('div');d.className='blq'+(/INSUMO/i.test(nb)?' ins':'');d.innerHTML='<h4>'+esc(nb)+'</h4><div class="bb"></div>';
  blqs[nb].forEach(function(it){var b=document.createElement('button');b.textContent=it.botao;if(!it.ok)b.style.opacity='.5';b.onclick=function(){abrirItem(it);};d.querySelector('.bb').appendChild(b);});
  box.appendChild(d);
});
